    # Raise the request-body cap (nginx default is 1 MiB) so the load balancer
    # does not reject large client requests with 413 before they reach the
    # frontend. Agentic replay traces (e.g. multi-turn cc-traces warmup bodies)
    # exceed 1 MiB; this mirrors the dynamo frontend's own body limit so nginx
    # is never the bottleneck and is never more permissive than the backend.
    client_max_body_size 45m;
    access_log off;

    # Keep a Dynamo session on one frontend. Anonymous requests use NGINX's
    # generated request ID so an empty session header cannot pin all traffic.

    map $http_x_dynamo_session_id $frontend_hash_key {
        default $http_x_dynamo_session_id;
        "" $request_id;
    }


    # Agentic replay reproduces recorded think-time, so a session's connection can
    # sit idle for minutes between turns. nginx's default keepalive_timeout of 75s
    # closes it underneath a pooled client connection, and the client's next write
    # on that socket surfaces as "broken pipe" / "server disconnected" with nothing
    # logged server-side.
    keepalive_timeout 600s;

    upstream backend_servers {

        hash $frontend_hash_key consistent;


        server $FRONTEND_0_IP:8180;

        server $FRONTEND_1_IP:8180;

        server $FRONTEND_2_IP:8180;

        server $FRONTEND_3_IP:8180;

        server $FRONTEND_4_IP:8180;

        server $FRONTEND_5_IP:8180;

        server $FRONTEND_6_IP:8180;

        server $FRONTEND_7_IP:8180;

        server $FRONTEND_8_IP:8180;

        # Reuse upstream connections instead of a fresh TCP handshake per request.
        keepalive 512;
        keepalive_timeout 600s;
    }

    # The main server block that listens for incoming traffic.
    server {
        listen 8000; # Public-facing port for incoming HTTP requests.

        location / {
            # Pass the request to the upstream group defined above.
            proxy_pass http://backend_servers;

            proxy_buffering off;
            proxy_read_timeout 24h;
            proxy_send_timeout 24h;

            # Required for the upstream keepalive pool above: without these nginx
            # talks HTTP/1.0 to the backend and opens a new connection per request.
            proxy_http_version 1.1;
            proxy_set_header Connection "";
        }
    }
}

events {

    #
    # Determines how many clients will be served by each worker process.
    # (Max clients = worker_connections * worker_processes)
    # Should be equal to `ulimit -n / worker_processes`
    #
    worker_connections 65535;

    #
    # Let each process accept multiple connections.
    # Accept as many connections as possible, after nginx gets notification
    # about a new connection.
    # May flood worker_connections, if that option is set too low.
    #
    multi_accept on;

    #
    # Preferred connection method for newer linux versions.
    # Essential for linux, optimized to serve many clients with each thread.
    #
    use epoll;
}"
